// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Ended drafts in history"
// Changes: Store tests for ended drafts: restoring one of their snapshots into a new open draft, deleting an ended
//          draft's history, and what project delete/duplicate do with ended drafts.

import { beforeEach, describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

const MINUTE = 60_000

let time: number
let store: ProjectStore
const advance = (ms: number) => {
  time += ms
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const withGrammar = (grammar: string): ProjectData => ({ ...defaultProjectData(), ll: { grammar, input: 'id' } })

/** A project with a discarded draft whose last grammar rules were `E -> d`. */
function discardedDraft() {
  const project = store.createProject('Výrazy', withGrammar('E -> id'))
  const draft = store.createDraft(project.id, 'Návrh', 'agent')!
  store.editDraft(draft.id, { grammarRules: 'E -> d', reductionRules: 'E -> d' }, { author: 'agent' })
  advance(MINUTE)
  store.discardDraft(draft.id)
  const final = store.listDraftSnapshots(draft.id)[0]
  return { project, draft: store.getDraft(draft.id)!, final }
}

describe('restoring a snapshot of an ended draft', () => {
  it("creates a new open draft forked from the project's current state, with the snapshot's parts and a derived label", () => {
    const { project, draft, final } = discardedDraft()
    // The project moved on after the draft ended.
    store.saveProject(project.id, withGrammar('E -> p'), project.revision)
    advance(MINUTE)
    const history = store.listDraftSnapshots(draft.id)

    const result = store.restoreEndedDraftSnapshot(draft.id, final.id)

    expect(result.status).toBe('saved')
    const fresh = result.status === 'saved' ? result.draft : null
    expect(fresh!.id).not.toBe(draft.id)
    expect(fresh).toMatchObject({
      projectId: project.id,
      label: 'Návrh (obnovený)',
      state: 'open',
      revision: 1,
      lastChangedBy: 'human',
      humanViewedRevision: 1,
      endedAt: null,
      createdAt: '2026-01-01T10:02:00.000Z',
      parts: { grammarRules: 'E -> d', reductionRules: 'E -> d' },
      base: { projectRevision: project.revision + 1, parts: { grammarRules: 'E -> p', reductionRules: '' } },
    })
    // The ended draft and its history stay as they were; the project is untouched.
    expect(store.getDraft(draft.id)).toEqual(draft)
    expect(store.listDraftSnapshots(draft.id)).toEqual(history)
    expect(store.listDraftSnapshots(fresh!.id)).toEqual([])
    expect(store.getProject(project.id)!.data.ll.grammar).toBe('E -> p')
    expect(store.listDrafts(project.id).map((d) => [d.id, d.state])).toEqual([
      [fresh!.id, 'open'],
      [draft.id, 'discarded'],
    ])
  })

  it('works from any snapshot of the ended draft, not just the final one', () => {
    const project = store.createProject('Výrazy', withGrammar('E -> id'))
    const draft = store.createDraft(project.id, 'Návrh', 'human')!
    store.editDraft(draft.id, { grammarRules: 'E -> a' }, { author: 'human' })
    const named = store.createDraftSnapshot(draft.id, 'Verzia A')
    store.editDraft(draft.id, { grammarRules: 'E -> b' }, { author: 'human' })
    store.adoptDraft(draft.id, ['grammarRules'], project.revision)

    const result = store.restoreEndedDraftSnapshot(draft.id, named.status === 'saved' ? named.snapshot.id : -1)
    expect(result).toMatchObject({ status: 'saved', draft: { parts: { grammarRules: 'E -> a' }, base: { parts: { grammarRules: 'E -> b' } } } })
  })

  it('a restored label stays within the label limit', () => {
    const project = store.createProject('Výrazy', withGrammar('E -> id'))
    const draft = store.createDraft(project.id, 'x'.repeat(200), 'agent')!
    store.discardDraft(draft.id)
    const result = store.restoreEndedDraftSnapshot(draft.id, store.listDraftSnapshots(draft.id)[0].id)
    expect(result.status === 'saved' && result.draft.label).toBe(`${'x'.repeat(189)} (obnovený)`)
  })

  it("an open draft restores into itself instead; a foreign or unknown snapshot is missing", () => {
    const { project, draft, final } = discardedDraft()
    const open = store.createDraft(project.id, 'Otvorený', 'agent')!
    const saved = store.createDraftSnapshot(open.id, 'V')
    const openSnapshot = saved.status === 'saved' ? saved.snapshot.id : -1

    expect(store.restoreEndedDraftSnapshot(open.id, openSnapshot)).toMatchObject({ status: 'open', draft: { id: open.id } })
    expect(store.restoreEndedDraftSnapshot(draft.id, openSnapshot)).toEqual({ status: 'missing' })
    expect(store.restoreEndedDraftSnapshot('nope', final.id)).toEqual({ status: 'missing' })
    expect(store.listDrafts(project.id)).toHaveLength(2)
  })
})

describe("deleting an ended draft's history", () => {
  it('removes the ended draft and all its snapshots; the project and its own history stay', () => {
    const { project, draft, final } = discardedDraft()
    store.createSnapshot(project.id, 'Projekt')

    expect(store.deleteEndedDraft(draft.id)).toEqual({ status: 'deleted' })

    expect(store.getDraft(draft.id)).toBeNull()
    expect(store.listDrafts(project.id)).toEqual([])
    expect(store.listDraftSnapshots(draft.id)).toEqual([])
    expect(store.getSnapshot(final.id)).toBeNull()
    expect(store.listSnapshots(project.id).map((s) => s.label)).toEqual(['Projekt'])
    expect(store.getProject(project.id)!.data.ll.grammar).toBe('E -> id')
  })

  it('an open draft is refused (discard it first); an unknown draft is missing', () => {
    const project = store.createProject('Výrazy', withGrammar('E -> id'))
    const open = store.createDraft(project.id, 'Otvorený', 'agent')!
    expect(store.deleteEndedDraft(open.id)).toMatchObject({ status: 'open', draft: { id: open.id } })
    expect(store.getDraft(open.id)).not.toBeNull()
    expect(store.deleteEndedDraft('nope')).toEqual({ status: 'missing' })
  })
})

describe('ended drafts and the project', () => {
  it('deleting a project removes its ended drafts and their snapshots', () => {
    const { project, draft, final } = discardedDraft()
    store.deleteProject(project.id)
    expect(store.getDraft(draft.id)).toBeNull()
    expect(store.getSnapshot(final.id)).toBeNull()
  })

  it('duplicating a project copies neither its open nor its ended drafts', () => {
    const { project } = discardedDraft()
    store.createDraft(project.id, 'Otvorený', 'agent')
    const copy = store.duplicateProject(project.id)!
    expect(store.listDrafts(copy.id)).toEqual([])
    expect(store.listSnapshots(copy.id)).toEqual([])
    expect(store.listDrafts(project.id)).toHaveLength(2)
  })
})
